"""Generate checklist of unverified and placeholder config values."""

from __future__ import annotations

import argparse
from pathlib import Path
from typing import Any

import yaml

UNIT_SUFFIXES = ("_db_mm_mhz", "_kg_m3", "_m_s", "_pct", "_mhz", "_mm")

HEADER_TEXT = (
    "# Verification Checklist\n\n"
    "Generated by `scripts/make_verification_checklist.py`.\n"
    "Values are placeholders until Ruri fills the `Verified against` column "
    "from a legitimate copy of the applicable standard or a primary source.\n\n"
)

TABLE_HEADER = (
    "| Config file | Key path | Current value | Unit hint | "
    "Source text | Verified against | Checked by |\n"
    "|---|---|---|---|---|---|---|\n"
)


def extract_unit_hint(key_path: str) -> str:
    """Extract unit hint from key path suffix or blank if none."""
    parts = key_path.split(".")
    for part in reversed(parts):
        for suffix in UNIT_SUFFIXES:
            if part.endswith(suffix):
                return suffix
    return ""


def is_unverified_text(text: Any) -> bool:
    """Return True if text contains UNVERIFIED or PLACEHOLDER markers."""
    if not isinstance(text, str):
        return False
    upper = text.upper()
    return any(marker in upper for marker in ("UNVERIFIED", "PLACEHOLDER"))


def extract_marker(mapping: dict[str, Any]) -> tuple[bool, str]:
    """Extract whether mapping is unverified and its source text."""
    src = mapping.get("source")
    if src is not None and is_unverified_text(src):
        return True, str(src)
    status = mapping.get("status")
    if status is not None and is_unverified_text(status):
        return True, str(status)
    return False, ""


def is_verified_mapping(mapping: dict[str, Any]) -> bool:
    """Return True if mapping has source/status without unverified markers."""
    has_meta = any(k in mapping for k in ("source", "status"))
    if not has_meta:
        return False
    has_unv = is_unverified_text(mapping.get("source")) or is_unverified_text(mapping.get("status"))
    return not has_unv


def _handle_dict_leaf(
    key: str,
    value: dict[str, Any],
    prefix: list[str],
) -> list[tuple[str, Any]]:
    """Recurse into child dictionary if not verified."""
    if is_verified_mapping(value):
        return []
    return _collect_leaves(value, prefix + [key])


def _collect_leaves(
    data: dict[str, Any],
    prefix: list[str],
) -> list[tuple[str, Any]]:
    """Collect numeric leaf paths and values from mapping."""
    leaves: list[tuple[str, Any]] = []
    for k, v in data.items():
        if k in ("source", "status"):
            continue
        if isinstance(v, dict):
            leaves.extend(_handle_dict_leaf(str(k), v, prefix))
        elif isinstance(v, (int, float)) and not isinstance(v, bool):
            leaves.append((".".join(prefix + [str(k)]), v))
    return leaves


def _find_unverified_mappings(
    data: dict[str, Any],
    prefix: list[str],
) -> list[tuple[list[str], dict[str, Any], str]]:
    """Find mappings with UNVERIFIED or PLACEHOLDER markers."""
    if is_verified_mapping(data):
        return []
    is_unv, src_text = extract_marker(data)
    if is_unv:
        return [(prefix, data, src_text)]
    results: list[tuple[list[str], dict[str, Any], str]] = []
    for k, v in data.items():
        if isinstance(v, dict):
            results.extend(_find_unverified_mappings(v, prefix + [str(k)]))
    return results


def _build_row(
    config_file: str,
    key_path: str,
    value: int | float,
    source_text: str,
) -> dict[str, Any]:
    """Construct checklist row dictionary for a single leaf."""
    hint = extract_unit_hint(key_path)
    return {
        "config_file": config_file,
        "key_path": key_path,
        "current_value": value,
        "unit_hint": hint,
        "source_text": source_text,
        "source": source_text,
        "verified_against": "",
        "checked_by": "",
    }


def _process_yaml_file(path: Path) -> list[dict[str, Any]]:
    """Parse single YAML file and extract unverified checklist rows."""
    with path.open("r", encoding="utf-8") as fh:
        data = yaml.safe_load(fh)
    if not isinstance(data, dict):
        return []
    mappings = _find_unverified_mappings(data, [])
    rows: list[dict[str, Any]] = []
    for prefix, mapping, src_text in mappings:
        leaves = _collect_leaves(mapping, prefix)
        for dot_path, val in leaves:
            rows.append(_build_row(path.name, dot_path, val, src_text))
    return rows


def collect_rows(config_dir: Path | str = "configs") -> list[dict[str, Any]]:
    """Walk config_dir for *.yaml and collect all unverified numeric leaves."""
    base_dir = Path(config_dir)
    if not base_dir.is_dir():
        return []
    yaml_files = sorted(base_dir.glob("*.yaml"))
    rows: list[dict[str, Any]] = []
    for yf in yaml_files:
        rows.extend(_process_yaml_file(yf))
    return rows


def _format_table_row(row: dict[str, Any]) -> str:
    """Format single row as markdown table line."""
    cfg = str(row.get("config_file", ""))
    key = str(row.get("key_path", ""))
    val = str(row.get("current_value", ""))
    unit = str(row.get("unit_hint", ""))
    src = str(row.get("source_text") or row.get("source") or "")
    src_escaped = src.replace("|", "\\|")
    ver = str(row.get("verified_against", ""))
    chk = str(row.get("checked_by", ""))
    return f"| {cfg} | {key} | {val} | {unit} | {src_escaped} | {ver} | {chk} |"


def render_markdown(rows: list[dict[str, Any]]) -> str:
    """Render checklist rows into markdown document with header and table."""
    body = "\n".join(_format_table_row(r) for r in rows)
    if body:
        body += "\n"
    return HEADER_TEXT + TABLE_HEADER + body


def main(argv: list[str] | None = None) -> None:
    """CLI entrypoint to generate verification checklist markdown."""
    parser = argparse.ArgumentParser(
        description="Generate verification checklist from YAML configs."
    )
    parser.add_argument(
        "--configs",
        type=Path,
        default=Path("configs"),
        help="Directory containing config YAML files",
    )
    parser.add_argument(
        "--out",
        type=Path,
        default=Path("docs/verification-checklist.md"),
        help="Output markdown file path",
    )
    args = parser.parse_args(argv)
    rows = collect_rows(args.configs)
    content = render_markdown(rows)
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(content, encoding="utf-8")
    print(f"Wrote {len(rows)} verification items to {args.out}")


if __name__ == "__main__":
    main()
